#include <bits/stdc++.h>
using namespace std;using U=uint32_t;using B=uint64_t;
const int K=0,Q=1,R=2,BI=3,N=4,P=5,INV=3,UNK=4,DEAD=2;
struct Pos{int s[4],turn,ep=0;};struct Move{int i,to,cap,pr,ep;};
struct Tab{int n,t[4],c[4],wk,sz,epn;vector<int8_t>v;string name;};
mutex outmu; vector<Tab>ts;int ids[6][6][2],rf[4][64],ray[64][8][8];B king[64],knight[64],pawn[2][64];int dx[]={1,-1,0,0,1,-1,1,-1},dy[]={0,0,1,-1,1,1,-1,-1};
int sq(int x,int y){return y*8+x;}bool ok(int x,int y){return x>=0&&x<8&&y>=0&&y<8;} B bit(int s){return 1ull<<s;}int pc(int v){return v==DEAD?0:v;}
void init(){for(int s=0;s<64;s++){int x=s%8,y=s/8;for(int r=0;r<4;r++)rf[r][s]=sq(r&1?7-x:x,r&2?7-y:y);for(int a=-2;a<=2;a++)for(int b=-2;b<=2;b++)if(ok(x+a,y+b)){B v=bit(sq(x+a,y+b));if(max(abs(a),abs(b))==1)king[s]|=v;if(abs(a*b)==2)knight[s]|=v;if(abs(a)==1&&b==1)pawn[0][s]|=v;if(abs(a)==1&&b==-1)pawn[1][s]|=v;}for(int d=0;d<8;d++){int k=0;for(int a=x+dx[d],b=y+dy[d];ok(a,b);a+=dx[d],b+=dy[d])ray[s][d][k++]=sq(a,b);ray[s][d][k]=-1;}}}
inline U enc(const Tab&t,Pos p){int r=(p.s[0]%8>=4)|((t.wk==16&&p.s[0]/8>=4)?2:0);if(r)for(int i=0;i<t.n;i++)p.s[i]=rf[r][p.s[i]];U a=p.s[0]/8*4+p.s[0]%8;for(int i=1;i<t.n;i++)a=a*64+p.s[i];return (a*2+p.turn)*t.epn+p.ep;}
inline Pos dec(const Tab&t,U a){Pos p{};p.ep=a%t.epn;a/=t.epn;p.turn=a&1;a>>=1;for(int i=t.n-1;i>=1;i--)p.s[i]=a&63,a>>=6;p.s[0]=a/4*8+a%4;return p;}
inline B occ(const Tab&t,const Pos&p){B b=0;for(int i=0;i<t.n;i++)if(p.s[i]>=0)b|=bit(p.s[i]);return b;}
inline bool att(const Tab&t,const Pos&p,int s,int col,B o){for(int i=0;i<t.n;i++)if(t.c[i]==col&&p.s[i]>=0){int z=p.s[i],a=t.t[i];if(a==K){if(king[z]&bit(s))return true;}else if(a==N){if(knight[z]&bit(s))return true;}else if(a==P){if(pawn[col][z]&bit(s))return true;}else{int X=s%8-z%8,Y=s/8-z/8;bool d=abs(X)==abs(Y),r=!X||!Y;if((!X&&!Y)||(a==BI&&!d)||(a==R&&!r)||(a==Q&&!d&&!r))continue;int step=(X>0)-(X<0)+8*((Y>0)-(Y<0));for(int q=z+step;;q+=step){if(q==s)return true;if(o&bit(q))break;}}}return false;}
inline bool epvalid(const Tab&t,const Pos&p){if(t.epn==1)return false;int a=p.s[2],b=p.s[3];if(!(abs(a%8-b%8)==1&&a/8==b/8&&a/8==(p.turn==0?4:3)))return false;int j=p.turn?2:3,step=p.turn?-8:8;B o=occ(t,p);if(o&(bit(p.s[j]+step)|bit(p.s[j]+2*step)))return false;Pos q=p;q.s[j]+=2*step;return !att(t,q,q.s[p.turn],1-p.turn,occ(t,q));}
inline bool valid(const Tab&t,const Pos&p){B o=occ(t,p);if(__builtin_popcountll(o)!=t.n)return false;for(int i=2;i<t.n;i++)if(t.t[i]==P&&(p.s[i]<8||p.s[i]>=56))return false;if(p.ep&&!epvalid(t,p))return false;return !att(t,p,p.s[1-p.turn],p.turn,o);}
template<class F>inline void moves(const Tab&t,const Pos&p,F f,bool only=false){B o=occ(t,p),own=0;for(int i=0;i<t.n;i++)if(t.c[i]==p.turn)own|=bit(p.s[i]);for(int i=0;i<t.n;i++)if(t.c[i]==p.turn){int z=p.s[i],a=t.t[i];auto go=[&](int q,int ec=-1,int ep=0){if(own&bit(q)||q==p.s[1-p.turn])return;int cap=ec;if(cap<0&&(o&bit(q)))for(int j=2;j<t.n;j++)if(p.s[j]==q)cap=j;if(only&&cap<0&&!(a==P&&(q<8||q>=56)))return;Pos v=p;v.s[i]=q;if(cap>=0)v.s[cap]=-1;if(att(t,v,v.s[p.turn],1-p.turn,occ(t,v)))return;if(a==P&&(q<8||q>=56)){for(int k=1;k<=4;k++)f(Move{i,q,cap,k,0},v);}else f(Move{i,q,cap,0,ep},v);};if(a==K||a==N){B b=(a==K?king[z]:knight[z])&~own;while(b){int q=__builtin_ctzll(b);b&=b-1;go(q);}}else if(a==P){int st=p.turn?-8:8,q=z+st;if(!(o&bit(q))){go(q);if(z/8==(p.turn?6:1)&&!(o&bit(q+st))){Pos v=p;v.s[i]=q+st;v.turn=1-p.turn;go(q+st,-1,epvalid(t,v));}}B b=pawn[p.turn][z]&o&~own;while(b){int q=__builtin_ctzll(b);b&=b-1;go(q);}if(p.ep) {int j=p.turn?2:3;go(p.s[j]+st,j);}}else for(int d=(a==BI?4:0);d<(a==R?4:8);d++)for(int k=0;ray[z][d][k]>=0;k++){int q=ray[z][d][k];go(q);if(o&bit(q))break;}}}
pair<int,Pos> child(const Tab&t,const Pos&p,Move m,Pos v){int typ[4];copy(t.t,t.t+4,typ);if(m.pr)typ[m.i]=m.pr;v.turn=1-p.turn;v.ep=m.ep;if(m.cap<0&&!m.pr)return {int(&t-&ts[0]),v};int w[2]={},b[2]={},nw=0,nb=0;for(int i=2;i<t.n;i++)if(v.s[i]>=0){if(t.c[i])b[nb++]=i;else w[nw++]=i;}bool sw=nw<nb||(nw==1&&nb==1&&typ[w[0]]>typ[b[0]]);if(sw){swap(nw,nb);swap(w,b);}if(nw==2&&typ[w[0]]>typ[w[1]])swap(w[0],w[1]);int a=nw?typ[w[0]]:0,bb=nw==2?typ[w[1]]:nb?typ[b[0]]:0;int id=ids[a][bb][nb>0];Pos q{};q.s[0]=v.s[sw?1:0];q.s[1]=v.s[sw?0:1];int k=2;for(int i=0;i<nw;i++)q.s[k++]=v.s[w[i]];for(int i=0;i<nb;i++)q.s[k++]=v.s[b[i]];q.turn=v.turn^sw;q.ep=v.ep;if(sw)for(int i=0;i<k;i++)q.s[i]^=56;return {id,q};}
int cv(const Tab&t,const Pos&p,Move m,Pos v){auto [id,q]=child(t,p,m,v);int z=ts[id].v[enc(ts[id],q)];assert(z!=INV&&z!=UNK);if(z!=DEAD&&q.turn!=1-p.turn)z=-z;return z;}
template<class F>inline void preds(const Tab&t,const Pos&p,F f){int turn=1-p.turn;B o=occ(t,p);for(int i=0;i<t.n;i++)if(t.c[i]==turn){int z=p.s[i],a=t.t[i];auto go=[&](int q,int dbl=0){if(o&bit(q))return;Pos v=p;v.s[i]=q;v.turn=turn;v.ep=0;if(a==P&&(q<8||q>=56))return;if(p.ep!=int(dbl&&epvalid(t,p)))return;if(att(t,v,v.s[1-turn],turn,occ(t,v)))return;f(enc(t,v));if(t.epn==2&&epvalid(t,v)){v.ep=1;f(enc(t,v));}};if(a==K||a==N){if(p.ep)continue;B b=(a==K?king[z]:knight[z])&~o;while(b){int q=__builtin_ctzll(b);b&=b-1;go(q);}}else if(a==P){int st=turn?8:-8,q=z+st;if(q>=0&&q<64&&!(o&bit(q))){go(q);if(z/8==(turn?4:3))go(q+st,1);}}else{if(p.ep)continue;for(int d=(a==BI?4:0);d<(a==R?4:8);d++)for(int k=0;ray[z][d][k]>=0;k++){int q=ray[z][d][k];if(o&bit(q))break;go(q);}}}}
string fen(const Tab&t,const Pos&p){char a[64];fill(a,a+64,' ');string c="KQRBNP";for(int i=0;i<t.n;i++)a[p.s[i]]=t.c[i]?tolower(c[t.t[i]]):c[t.t[i]];string o;for(int r=7;r>=0;r--){int n=0;for(int x=0;x<8;x++){char c=a[r*8+x];if(c==' ')n++;else{if(n)o+=char('0'+n),n=0;o+=c;}}if(n)o+=char('0'+n);if(r)o+='/';}o+=p.turn?" b - ":" w - ";if(p.ep){int q=p.s[p.turn?2:3]+(p.turn?-8:8);o+=char('a'+q%8);o+=char('1'+q/8);}else o+='-';return o+" 0 1";}
string uci(const Pos&p,Move m){string s;for(int q:{p.s[m.i],m.to})s+=char('a'+q%8),s+=char('1'+q/8);if(m.pr)s+=string(" kqrbn")[m.pr+1];return s;}
string mat(const Tab&t,bool sw=false){string s="K",b="K",c="KQRBNP";for(int i=2;i<t.n;i++)(t.c[i]?b:s)+=c[t.t[i]];return sw?b+"v"+s:s+"v"+b;}
string targetmat(const Tab&t,const Pos&p,Move m,Pos v){auto [i,q]=child(t,p,m,v);return mat(ts[i],q.turn!=1-p.turn);}
void solve(int id){Tab&t=ts[id];int S=t.sz;t.v.assign(S,INV);vector<uint8_t>deg(S),live(S);vector<U>q,lq;q.reserve(S/2);lq.reserve(S/2);long cnt=0;for(U a=0;a<(U)S;a++){Pos p=dec(t,a);if(!valid(t,p))continue;cnt++;int win=0,nn=0,li=0,sign=p.turn?-1:1,total=0;moves(t,p,[&](Move m,Pos v){total++;nn++;if(m.cap>=0||m.pr){int z=cv(t,p,m,v);if(z!=DEAD)li=1;z=pc(z);if(z==sign)win=1;else if(z==-sign)nn--;}});bool mate=!total&&att(t,p,p.s[p.turn],1-p.turn,occ(t,p));if(mate)li=1;if(!total&&!mate){t.v[a]=0;continue;}if(li){live[a]=1;lq.push_back(a);}if(win||mate||!nn){t.v[a]=win?sign:-sign;q.push_back(a);}else{t.v[a]=UNK;deg[a]=nn;}}
for(size_t j=0;j<q.size();j++){U a=q[j];Pos p=dec(t,a);int z=t.v[a];preds(t,p,[&](U b){if(t.v[b]!=UNK)return;int sign=p.turn?1:-1;if(z==sign){t.v[b]=z;q.push_back(b);}else if(--deg[b]==0){t.v[b]=z;q.push_back(b);}});}
for(size_t j=0;j<lq.size();j++){Pos p=dec(t,lq[j]);preds(t,p,[&](U b){if(!live[b]){live[b]=1;lq.push_back(b);}});}
long counts[5]={};for(U a=0;a<(U)S;a++)if(t.v[a]!=INV){if(t.v[a]==UNK)t.v[a]=0;if(!live[a]){assert(t.v[a]==0);t.v[a]=DEAD;}counts[t.v[a]+1]++;}
map<tuple<string,string,int>,pair<string,string>>edges;map<int,string>vertices;for(U a=0;a<(U)S;a++){int z=t.v[a];if(z==INV)continue;Pos p=dec(t,a);vertices.try_emplace(pc(z),fen(t,p));if(z==DEAD)continue;moves(t,p,[&](Move m,Pos v){if(m.cap<0&&!m.pr)return;int zz=cv(t,p,m,v);if(pc(zz)!=z)return;auto k=make_tuple(t.name,targetmat(t,p,m,v),z);if(!edges.count(k))edges[k]={fen(t,p),uci(p,m)};},true);}
lock_guard<mutex> lk(outmu); ofstream f("results.tsv",ios::app);for(auto &[z,s]:vertices)f<<"V\t"<<t.name<<"\t"<<z<<"\t"<<s<<"\n";for(auto &[k,v]:edges){auto [a,b,z]=k;f<<"E\t"<<a<<"\t"<<b<<"\t"<<z<<"\t"<<v.first<<"\t"<<v.second<<"\n";}f.close();cerr<<t.name<<" "<<cnt<<" W "<<counts[2]<<" D "<<counts[1]<<" dead "<<counts[3]<<" L "<<counts[0]<<" edges "<<edges.size()<<endl;ofstream o("tb_"+t.name+".bin",ios::binary);o.write((char*)t.v.data(),t.v.size());}
void setup(){memset(ids,-1,sizeof(ids));auto add=[&](int a,int b,int split){Tab t{};t.n=2+(a!=0)+(b!=0);t.t[2]=a;t.t[3]=b;t.c[0]=0;t.c[1]=1;t.c[2]=0;t.c[3]=split;t.wk=a==P||b==P?32:16;t.epn=a==P&&b==P&&split?2:1;t.sz=t.wk*2*t.epn;for(int i=1;i<t.n;i++)t.sz*=64;t.name=mat(t);ids[a][b][split]=ts.size();ts.push_back(move(t));};add(0,0,0);for(int a=1;a<=5;a++)add(a,0,0);for(int p=0;p<=2;p++)for(int a=1;a<=5;a++)for(int b=a;b<=5;b++)if((a==P)+(b==P)==p){add(a,b,0);add(a,b,1);}}
void load(){for(auto&t:ts){t.v.resize(t.sz);ifstream f("tb_"+t.name+".bin",ios::binary);f.read((char*)t.v.data(),t.sz);assert(f.gcount()==t.sz);}}
int main(){init();setup();remove("results.tsv");for(int i=0;i<6;i++)solve(i);for(int np=0;np<=2;np++){vector<int>jobs;for(int i=6;i<(int)ts.size();i++)if((ts[i].t[2]==P)+(ts[i].t[3]==P)==np)jobs.push_back(i);atomic<int>j{0};vector<thread>th;for(int k=0;k<4;k++)th.emplace_back([&]{for(;;){int x=j++;if(x>=jobs.size())break;solve(jobs[x]);}});for(auto&x:th)x.join();}return 0;}
